import static org.assertj.core.api.Assertions.assertThat;

import org.mockito.ArgumentCaptor;
import org.mockito.Captor;

@Captor
ArgumentCaptor<Mail> mailCaptor;

@Test
void sendsWelcomeMail() {
    signupService.register("alice@example.com", "Alice");

    verify(mailSender).send(mailCaptor.capture());
    Mail mail = mailCaptor.getValue();
    assertThat(mail.to()).isEqualTo("alice@example.com");
    assertThat(mail.subject()).contains("Alice");
}

import static org.mockito.Mockito.times;

@Test
void notifiesInviter() {
    signupService.register("alice@example.com", "Alice", "bob@example.com");

    verify(mailSender, times(2)).send(mailCaptor.capture());
    assertThat(mailCaptor.getAllValues())
        .extracting(Mail::to)
        .containsExactly("alice@example.com", "bob@example.com");
}
